alter policy recipe_photos_read on storage.objects using (bucket_id='recipe-photos' and exists(select 1 from public.recipes r where r.id::text=split_part(storage.objects.name,'/',1)));
alter policy recipe_photos_insert on storage.objects with check (bucket_id='recipe-photos' and (select auth.uid()) is not null and coalesce(auth.jwt()->>'email','')<>'' and auth.jwt()->>'email'<>'cucina@officinaventidue.it' and exists(select 1 from public.recipes r where r.id::text=split_part(storage.objects.name,'/',1)));
alter policy recipe_photos_delete on storage.objects using (bucket_id='recipe-photos' and (select auth.uid()) is not null and coalesce(auth.jwt()->>'email','')<>'' and auth.jwt()->>'email'<>'cucina@officinaventidue.it' and exists(select 1 from public.recipes r where r.id::text=split_part(storage.objects.name,'/',1)));
